<?php
namespace App\Services\Trading;
class PositionManagementReferenceSelectionPolicyService extends EntryReferenceSelectionPolicyService
{public function evaluate(array $ctx):array{$p=$ctx['management_reference_selection_policy']??null;$cand=$ctx['management_candidate']??null;$plan=$ctx['action_plan']??null;$approval=$ctx['management_portfolio_approval']??null;$codes=[];$warnings=[];$blockers=[];$checks=[];$status='unavailable';$elig='policy_unavailable';
 if(!is_array($p))$this->add($codes,'POSITION_MANAGEMENT_REFERENCE_SELECTION_POLICY_UNAVAILABLE',$blockers);elseif(($p['schema_version']??null)!==$this->config['management_policy_schema_version']||$this->invalidMgmt($p,$codes,$blockers)){$status='invalid';$elig='invalid';}else{if(($p['position_id']??null)!==($plan['position_id']??null)||($p['management_candidate_id']??null)!==($cand['candidate_id']??null)||($p['action_plan_id']??null)!==($plan['action_plan_id']??null)||($p['proposed_quantity_reference']??null)!=($plan['quantity_plan']['proposed_quantity_reference']??null)){$status='blocked';$elig='identity_mismatch';$this->add($codes,'POSITION_MANAGEMENT_REFERENCE_SELECTION_IDENTITY_MISMATCH',$blockers);}else{$checks=$this->checksMgmt($p,$ctx);$failed=false;$un=false;foreach($checks as $c){if($c['passed']===false)$failed=true;if($c['passed']===null)$un=true;}if(!($p['approved_for_reference_selection']??false)){$status='denied_reference_selection';$elig='denied_reference_selection';$this->add($codes,'POSITION_MANAGEMENT_REFERENCE_SELECTION_DENIED',$blockers);}elseif($failed){$status='blocked';$elig='requirement_failed';$this->add($codes,'POSITION_MANAGEMENT_REFERENCE_SELECTION_REQUIREMENT_FAILED',$blockers);}elseif($un){$status='incomplete';$elig='requirement_unavailable';$this->add($codes,'POSITION_MANAGEMENT_REFERENCE_SELECTION_REQUIREMENT_UNAVAILABLE',$blockers);}else{$status='eligible_for_reference_selection';$elig='eligible_for_reference_selection';$this->add($codes,'POSITION_MANAGEMENT_REFERENCE_SELECTION_ELIGIBLE');}$this->add($codes,'POSITION_MANAGEMENT_REFERENCE_SELECTION_REFERENCE_ONLY');}}
 return ['schema_version'=>$this->config['management_policy_evaluation_schema_version'],'status'=>$status,'selection_scope'=>'management_action_reference','policy_id'=>$p['policy_id']??null,'policy_version'=>$p['policy_version']??null,'portfolio_id'=>$p['portfolio_id']??($approval['portfolio_id']??null),'position_id'=>$p['position_id']??($plan['position_id']??null),'management_candidate_id'=>$p['management_candidate_id']??($cand['candidate_id']??null),'action_plan_id'=>$p['action_plan_id']??($plan['action_plan_id']??null),'proposed_management_action'=>$p['proposed_management_action']??($plan['proposed_management_action']??null),'proposed_quantity_reference'=>$p['proposed_quantity_reference']??($plan['quantity_plan']['proposed_quantity_reference']??null),'requirement_checks'=>$checks,'all_required_checks_passed'=>$status==='eligible_for_reference_selection','reference_selection_allowed'=>$status==='eligible_for_reference_selection','production_selection_allowed'=>false,'execution_allowed'=>false,'eligibility'=>$elig,'reason_codes'=>$this->ordered($codes),'warnings'=>$this->ordered($warnings),'blockers'=>$this->ordered($blockers),'metadata'=>[]];}
 protected function checksMgmt($p,$ctx){$map=['management_candidate_valid'=>[$ctx['management_candidate']??[],'policy_hypothesis'],'management_risk_evaluated'=>[$ctx['management_risk']??[],['condition_risk_observed','evaluated_reference']],'review_context_ready'=>[$ctx['review_plan']??[],'review_context_ready'],'action_policy_matched'=>[$ctx['action_policy_evaluation']??[],'matched_reference_rule'],'action_plan_materialized'=>[$ctx['action_plan']??[],'materialized_reference'],'impact_simulated'=>[$ctx['impact_simulation']??[],'simulated_reference'],'management_reference_approved'=>[$ctx['management_portfolio_approval']??[],'approved_reference']];$out=[];foreach($p['requirements']??[] as $k=>$req){$src=$map[$k][0]??null;$expect=$map[$k][1]??null;$evaluated=is_array($src);$st=$src['status']??null;$passed=null;if($evaluated)$passed=is_array($expect)?in_array($st,$expect,true):$st===$expect;$out[]=['key'=>$k,'required'=>(bool)$req,'evaluated'=>$evaluated,'passed'=>$req?$passed:true,'source_status'=>$st,'reason_code'=>'POSITION_MANAGEMENT_REFERENCE_SELECTION_'.$k];}return $out;}
 protected function invalidMgmt($p,&$codes,&$blockers){$bad=false;foreach(['policy_id','policy_version','selection_scope','selection_mode','portfolio_id','position_id','management_candidate_id','action_plan_id','proposed_management_action','proposed_quantity_reference','requirements','source'] as $k)if(!array_key_exists($k,$p)||$p[$k]==='')$bad=true;if(($p['selection_scope']??null)!=='management_action_reference'||($p['selection_mode']??null)!=='single_proposal_reference')$bad=true;foreach(array_keys($p['requirements']??[]) as $k)if(!in_array($k,$this->config['management_requirement_keys'],true))$bad=true;if(($p['approved_for_production_selection']??false)||($p['approved_for_execution']??false))$bad=true;if($bad)$this->add($codes,'POSITION_MANAGEMENT_REFERENCE_SELECTION_POLICY_INVALID',$blockers);return $bad;}}
